import {professionalCostPanel,graduateAidPanel,needsFurtherStudy} from './education-evidence-ui.js?v=0.31.0';
import {salaryPanel} from './salary-ui.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
import {directions} from './content.js?v=0.31.0';
import {careers,pathCareers,collegeExamples,financeSources,wageCenter,wageCaption} from './finance-data.js?v=0.31.0';
import {subjectLink} from './catalog-data.js?v=0.31.0';
import {calculateCollege,linkedPlans,requirementContext} from './finance.js?v=0.31.0';
const usd=n=>n===null||n===undefined?'Not published':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const ext=(label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${h(label)} ↗</a>`;
const more=(body,label='More info')=>`<details class="more-info"><summary>${label}</summary><div>${body}</div></details>`;
const header=(title,copy,back='catalog')=>`<div class="page-intro context-intro"><div><span class="eyebrow">AUSTIN, TEXAS</span><h1>${h(title)}</h1><p class="intro-copy">${h(copy)}</p></div><a class="button secondary" href="#/${back}">Browse ${back==='catalog'?'careers':'pathways'} ↗</a></div>`;
const mini=c=>`<a class="career-mini" href="#/career/${c.id}"><h3>${h(c.title)}</h3><b>${usd(wageCenter(c.earnings))}</b><p>${wageCaption(c.earnings)}</p></a>`;
function distributionPanel(c){const w=c.earnings,posting=w.status==='posting_estimate',center=wageCenter(w),range=Number.isFinite(w.p25)&&Number.isFinite(w.p75),max=range?Math.ceil(w.p75*1.1/25000)*25000:null;return `<section class="context-panel earnings-panel"><span class="overline">${posting?'AUSTIN POSTING ESTIMATE':'AUSTIN PAY'}</span><h2>${usd(center)}</h2><p>${posting?'Average advertised base pay. Small sample. Before tax.':'Median yearly employee pay. Before tax.'}</p>${posting?`<div class="pay-stats"><div><span>Austin · ${w.sampleSize} posts</span><strong>${usd(w.average)}</strong></div>${w.regionalComparisons.map(x=>`<div><span>${h(x.city)} · ${x.sampleSize} posts</span><strong>${usd(x.average)}</strong></div>`).join('')}</div><p>City averages, not a wage range. Studio costs can reduce take-home.</p>`:`<div class="pay-stats"><div><span>Lower quarter</span><strong>${usd(w.p25)}</strong></div><div><span>Median</span><strong>${usd(center)}</strong></div><div><span>Upper quarter</span><strong>${usd(w.p75)}</strong></div></div>${range?`<figure class="wage-chart"><figcaption>Middle half of Austin employee wages</figcaption><div class="wage-track" role="img" aria-label="25th percentile ${usd(w.p25)}, median ${usd(center)}, 75th percentile ${usd(w.p75)}"><span class="wage-middle" style="left:${w.p25/max*100}%;width:${(w.p75-w.p25)/max*100}%"></span><i style="left:${center/max*100}%"></i></div><div class="wage-axis"><span>$0</span><span>${usd(max)}</span></div></figure>`:'<p>The middle-half range is not published.</p>'}`}<a class="button" href="#/lifestyle/${c.id}">See the Austin lifestyle →</a>${posting?'<a class="button secondary" href="#/money/business">Studio business budget →</a>':''}${more(`<p>${h(c.officialTitle||c.title)} · ${posting?'Posting title; no tattoo-specific BLS wage series.':'SOC '+h(c.soc)+'.'}</p><p>${h(w.geography)} · ${h(w.referencePeriod)} · USD, ${w.dollarYear} dollars.</p>${posting?`<p>${h(w.reason)} Austin uses ${w.sampleSize} salary-bearing postings from the preceding 36 months. Dallas: updated April 7, 2026; Houston: July 6, 2026. Samples may overlap employers or miss independent studios. These are advertised amounts, not audited take-home income.</p><p>${w.regionalComparisons.map(x=>ext(x.city+' source',x.sourceURL)).join(' · ')}</p>`:'<p>Half of observed employee wages are above the median; half are below. Quartiles are not starting pay or years of experience. Self-employed workers and employer benefits are excluded.</p>'}<p>${h(w.population)}. ${h(w.annualization||'')}</p><p>No reliable experience-year series is used. ${ext('Published pay source',w.sourceURL)} · ${ext(posting?'Source explanation':'BLS methods',w.methodURL)}. Retrieved October 16, 2026.</p>`)}</section>`;}
export function educationCostsPanel(state,entityId){const further=needsFurtherStudy(entityId),ps=linkedPlans(state.finance,entityId),c=careers.find(c=>c.id===entityId),training=c?.routeType==='training'||directions.find(d=>d.id===entityId)?.routeType==='training';const examples=collegeExamples.filter(e=>['ut-austin-resident','acc-district'].includes(e.id));return `<section class="context-panel" data-coverage="educationCosts"><span class="overline">EDUCATION COSTS & AID</span><h2>${further?'College, then your professional preparation.':training?'Training is an investment.':'Two local cost benchmarks.'}</h2>${professionalCostPanel(entityId)}${graduateAidPanel(entityId)}${further?'<strong class="cost-stage-label">Undergraduate foundation · a separate cost</strong>':''}${training?'<p>Apprenticeships, certificates, and college have different prices.</p>':'<p>One academic year. Before grants or scholarships.</p>'}<div class="cost-benchmark-cards">${examples.map(e=>`<article><h3>${h(e.institution)}</h3><b>${usd(e.tuitionMin)}${e.tuitionMax!==e.tuitionMin?'–'+usd(e.tuitionMax):''}</b><span>tuition${e.id==='acc-district'?' & fees':''} / academic year</span><p>${h(e.residency)}</p><p><strong>${e.id==='acc-district'?'Free tuition for eligible local graduates.':'Tuition support for eligible Texas families.'}</strong></p>${more(`<p>2026–27 · ${h(e.enrollment)} · ${h(e.living)}. Total published cost: ${usd(e.totalMin)}${e.totalMax!==e.totalMin?'–'+usd(e.totalMax):''}. Includes living costs.</p><p>${h(e.note)} These are institution-wide examples, not a career’s program price or proof a school offers that credential.</p><p>${ext('Published college budget',e.sourceURL)}</p>${e.id==='acc-district'?`<p>ACC: local high school or homeschool graduates from spring 2024–August 2028 may receive 3 consecutive years of credit tuition and general fees, or 5 for an ACC bachelor’s. Service-area residence and qualifying graduation apply. No income or GPA threshold. Out-of-district charges, books, supplies, and course fees remain. International students are excluded. Starts the fall after graduation; registration triggers review. GED routes also exist.</p><p>${ext('ACC free tuition rules','https://www.austincc.edu/paying-for-college/acc-free-tuition/')}</p>`:`<p>UT Texas Advance Commitment: tuition coverage for eligible families with AGI up to $100,000; partial support through $125,000. Requires Texas residency, demonstrated need, FAFSA/TASFA, and a first bachelor’s degree. Published entry criteria specify full-time enrollment. Annual renewal requires financial eligibility and academic progress, including 2.0 GPA and 67% completion. Living costs remain. Admission and an individual award are not assumed.</p><p>${ext('UT tuition support rules','https://admissions.utexas.edu/cost-aid/financial-aid/texas-advance-commitment/')}</p>`}`)}</article>`).join('')}</div>${ps.length?`<div class="linked-costs">${ps.map(p=>`<article><h3>${h(p.institution||'My education plan')}</h3><strong>${usd(calculateCollege(p).netPrice)} net price</strong><p>${h(p.program)} · ${h(p.year)}</p></article>`).join('')}</div>`:''}<div class="aid-equation"><span>College cost</span><b>−</b><span>Grants</span><b>=</b><strong>Your net price</strong></div><p>Loans fund the price. They do not lower it.</p><a class="button secondary" href="#/money">Build my education budget →</a>${more(`<p>${training?'Paid apprenticeship income is earned pay, not a tuition discount. Training fees, tools, exams, travel, and unpaid time belong in the budget. Federal aid applies only to eligible programs.':'Tuition depends on your program and residency. Living costs depend on where you live. Graduate and professional credentials add further costs.'}</p><p>Grant amounts depend on your financial aid offer. No family income or award is assumed. Work-study requires earned work. The FAFSA Student Aid Index is not a bill. Renewal conditions remain attached to saved offers.</p><p>${ext('Federal Student Aid: compare offers',financeSources.aid)} · ${ext('Texas aid', 'https://www.highered.texas.gov/our-work/supporting-our-institutions/student-financial-aid-programs/')}</p>`)}</section>`;}
export function careerDetail(id,state={},options={}){const c=careers.find(x=>x.id===id);if(!c)return header('Career not found.','Choose a career from the catalog.');const safeState={...state,finance:state.finance||{plans:[]}},legal=requirementContext(c,safeState.finance),pageHeader=options.embedded?'':header(c.title,'The preparation. The pay. The life it could support.');return `${pageHeader}<div class="career-breadcrumbs">${Object.entries(pathCareers).filter(([,ids])=>ids.includes(id)).map(([pid])=>`<a href="#/path/${pid}">${h(directions.find(d=>d.id===pid).title)} ↗</a>`).join('')}</div>${earningsPanel(c)}<div class="context-two"><section class="context-panel" data-coverage="educationRoutes"><span class="overline">EDUCATION & TRAINING</span><h2>${c.routeType==='training'?'Learn through training.':c.credentialLevel==='graduate'?'Plan beyond a bachelor’s.':'Build a college foundation.'}</h2><div class="tags">${c.educationRoutes.routes.slice(0,3).map(r=>`<span class="tag">${h(r)}</span>`).join('')}</div><p>${h(c.requirements.typicalEntry)}</p>${c.routeType==='training'?'<p>College can broaden your long-term options.</p>':''}${more(`<p>${h(c.educationBenefits)}</p><p>${h(c.requirements.training)}</p><p>${ext('Education and training source',c.sourceURL)}</p>`)}</section><section class="context-panel" data-coverage="requirements"><span class="overline">TEXAS REQUIREMENTS</span><h2>${h(legal.summary||'Your route into the work.')}</h2>${legal.bullets?`<ul>${legal.bullets.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:`<p>${h(legal.text)}</p>`}${more(`<p>${h(legal.detail||legal.text)}</p><p>${(legal.sourceURLs||[legal.sourceURL]).filter(Boolean).map((u,i)=>ext('Texas source '+(i+1),u)).join(' · ')}</p><p>Reviewed October 16, 2026. Requirements describe Texas entry routes, not an individual eligibility decision.</p>`)}</section></div>${educationCostsPanel(safeState,id)}<section class="context-panel"><span class="overline">TRY THE WORK</span><h2>Build evidence about yourself.</h2><div class="button-group"><a class="button secondary" href="${c.skillsURL}" target="_blank" rel="noopener noreferrer">Tasks & skills ↗</a><a class="button secondary" href="#/results">My interests & evidence →</a>${id==='tattoo'?'<a class="button secondary" href="#/money/business">Tattoo business budget →</a>':''}</div>${more('<p>O*NET describes occupational tasks, skills, abilities, and interests. These are exploration resources. They do not measure your personal aptitude. Income never changes your interest profile.</p>')}</section>`;}
export function pathDetail(id,state){const d=directions.find(x=>x.id===id);if(!d)return header('Pathway not found.','Choose a pathway.','directions');const cs=(pathCareers[id]||[]).map(id=>careers.find(c=>c.id===id));return `${header(d.title,d.description,'directions')}<section class="context-panel" data-coverage="educationRoutes"><span class="overline">WHAT YOU COULD STUDY</span><h2>${h(d.eyebrow)}</h2><div class="tags">${d.subjects.map(s=>`<a class="tag" href="${subjectLink(s)}">${h(s)} ↗</a>`).join('')}</div>${more(`<p>${h(d.learn)}</p><p>These are exploration links, not an admissions or degree-to-license guarantee.</p>`)}</section><section class="context-panel" data-coverage="requirements"><span class="overline">ROUTES INTO THE WORK</span><h2>Choose a specific career.</h2><div class="career-mini-grid">${cs.map(mini).join('')}</div><p>Each career includes its Texas requirements.</p></section>${educationCostsPanel(state,id)}<section class="context-panel" data-coverage="earnings"><span class="overline">AUSTIN FINANCIAL PICTURE</span><h2>Different careers. Different pay.</h2><div class="career-mini-grid">${cs.map(mini).join('')}</div>${more('<p>There is no single pathway salary. Each published median describes an exact occupation and Austin metro employee population.</p>')}</section><section class="counselor-card"><span class="overline">ONE SMALL EXPERIMENT</span><h2>${h(d.activity)}</h2>${more(`<p>${h(d.detail)}</p><p>${h(d.question)}</p>`)}<button class="button secondary" data-action="add-direction" data-id="${d.id}">Add to my next steps +</button></section>`;}

export function earningsPanel(c){return salaryPanel(c)+more(distributionPanel(c),'Wage distribution details');}
